content.query:
let gates = LogicAppWorkflowRuntime
| where TimeGenerated > ago({TimeRange:seconds}s)
| where ActionName == "Human_approval_gate" or ActionName startswith "Wait_for_approval_";
let started = gates | where OperationName =~ "Microsoft.Logic/workflows/workflowActionStarted" | project WorkflowName, RunId, ActionName, StartedAt = TimeGenerated;
let completed = gates | where OperationName =~ "Microsoft.Logic/workflows/workflowActionCompleted" | project RunId, ActionName;
started
| join kind=leftanti completed on RunId, ActionName
| extend ageHours = datetime_diff('hour', now(), StartedAt)
| project WorkflowName, RunId, ActionName, StartedAt, ageHours
| order by ageHours desc
